state.activeProjectId ||= 'p1'; state.projectData ||= {};
function stashProject(){state.projectData[state.activeProjectId]=Object.fromEntries(projectKeys.map(k=>[k,structuredClone(state[k])]));}
function selectProject(id){stashProject();const p=state.projects.find(p=>p.id===id);if(!state.projectData[id]){const base=seed();base.projectTitle=p.title;base.projectGoal='围绕'+p.title+'整理证据、明确分歧并形成研究成果。';base.materials=[{id:1,title:'项目背景（合成）',text:'这是关于'+p.title+'的合成研究背景。现有观察只能作为提出问题的依据，尚不足以形成因果结论，需要补充对照材料与连续记录。'}];base.session={stage:'draft',summary:'none',round:0,pending:[],completed:[],messages:[],lastError:'',interrupted:false,offline:false};base.output='';base.version=0;base.versions=[];base.tasks=seed().tasks.map(t=>({...t,title:t.id==='T-01'?'梳理项目材料证据':t.id==='T-02'?'检验结论的适用边界':'整合研究方案',status:t.id==='T-01'?'待执行':'等待依赖',attempts:[],applied:false}));base.events=[{text:'项目尚待规划问题',actor:'host',type:'项目',time:'合成示例'}];state.projectData[id]=Object.fromEntries(projectKeys.map(k=>[k,base[k]]));}Object.assign(state,structuredClone(state.projectData[id]));state.activeProjectId=id;state.selectedMaterial=state.materials[0].id;state.editing=false;state.selectedTask='T-02';}
